            CameraLayoutCorner.allCases.map {
                CameraLayoutChoice(kind: .corner, shape: shape, corner: $0)
            }
        }
        + [.sideBySide, .stacked, .cameraFull, .screenOnly].map {
            CameraLayoutChoice(kind: $0, shape: nil, corner: nil)
        }

