        guard !plan.ops.isEmpty else { return nil }
        let step = CaptionRetime.withRetime(
            SpeedUpTyping.actionName, speechOps + plan.ops, on: document.editedProject)
        let crossing =
            SpeedAudioDrop.mayCross(step.ops)
